using System;using System.IO;using System.Collections.Generic;using System.Threading;using OsuLegacy;
public static class OnlineBrowserTests {
 static int checks;static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}static void Wait(Func<bool> ready,string name){DateTime end=DateTime.UtcNow.AddSeconds(5);while(!ready()){if(DateTime.UtcNow>end)throw new Exception("Timeout: "+name);Thread.Sleep(5);}}
 static string Set(int id,string title){return "[{\"SetID\":"+id+",\"Title\":\""+title+"\",\"Artist\":\"Artist\",\"Creator\":\"Mapper\",\"RankedStatus\":1,\"ChildrenBeatmaps\":[{\"BeatmapID\":10,\"Mode\":0,\"DiffName\":\"Hard\",\"DifficultyRating\":5.2}]}]";}
 sealed class Fake:IMirrorTransport {public volatile bool SlowStarted,Fail,BadZip,HoldDownload;public string LastDownload;public int Searches;
  public void Fetch(string path,string target,int maximum,Func<bool> cancel,Action<int,int> progress){if(path.Contains("/cover/"))throw new IOException("No fixture cover");if(path.Contains("/d/")){LastDownload=path;while(HoldDownload && !cancel())Thread.Sleep(5);if(cancel())throw new OperationCanceledException();File.WriteAllBytes(target,BadZip?new byte[30]:File.ReadAllBytes("port/Tests/Fixtures/mirror-download.osz"));if(progress!=null)progress(100,100);return;}Interlocked.Increment(ref Searches);if(path.Contains("query=slow")){SlowStarted=true;Wait(delegate{return cancel();},"cancel slow request");throw new OperationCanceledException();}if(Fail)throw new IOException("Offline");File.WriteAllText(target,path.Contains("offset=24")?"[]":Set(path.Contains("offset=12")?2:1,path.Contains("query=fast")?"Fast":"Fixture"));}
 }
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"osu-browser-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
  var real=MirrorSet.Parse(File.ReadAllText("port/Tests/Fixtures/hinai-search.json"));Check(real.Count==2 && real[0].Artist=="xi" && real[0].Difficulties.Count>0,"real Hinamizawa response parses");Check(real[0].MinStars<=real[0].MaxStars,"star ranges");Check(MirrorQuery.Encode("xi & 日本") == "xi%20%26%20%E6%97%A5%E6%9C%AC","UTF-8 query escaping");var query=new MirrorQuery{Text="a&mode=3",Mode=0};Check(query.Path(12).Contains("query=a%26mode%3D3") && query.Path(12).Contains("&offset=12&mode=0"),"search values cannot inject URL parameters");
  foreach(string invalid in new[]{"{}","[","[1e9999]","[01]","[1,]","[NaN]","[\"bad\\q\"]"}){bool failed=false;try{MirrorSet.Parse(invalid);}catch(FormatException){failed=true;}Check(failed,"malformed responses rejected: "+invalid);}
  Check(MirrorSet.Parse("[{\"SetID\":-1},{\"SetID\":5},{\"SetID\":5}]").Count==1,"invalid and duplicate IDs rejected");
  var fake=new Fake();var browser=new OnlineBeatmaps(root,fake);browser.Search(false);Wait(delegate{browser.Poll();return !browser.Searching && browser.Results.Count==1;},"first search");Check(browser.HasMore,"short pages remain pageable");var rated=browser.Results[0];if(rated.Difficulties.Count>0){var diff=rated.Difficulties[0];Check(browser.Rating(rated.Id,diff.Mode,diff.Name)==diff.Stars,"Mirror rating is matched by set, ruleset and difficulty");var restored=new OnlineBeatmaps(root,fake);Check(restored.Rating(rated.Id,diff.Mode,diff.Name)==diff.Stars,"Known ratings persist for offline Solo cards");Check(restored.Rating(rated.Id,(diff.Mode+1)%4,diff.Name)<0,"Converted rulesets never reuse native rating");}browser.Search(true);Wait(delegate{browser.Poll();return !browser.Searching && browser.Offset==12;},"next page");Check(browser.Results.Count==2,"paging appends results");browser.Search(true);Wait(delegate{browser.Poll();return !browser.Searching && !browser.HasMore;},"end of pages");Check(browser.Results.Count==2,"empty page ends feed without deleting results");
  browser.Query.Text="slow";browser.Search(false);Wait(delegate{return fake.SlowStarted;},"slow starts");browser.Query.Text="fast";browser.Search(false);Wait(delegate{browser.Poll();return !browser.Searching && browser.Results.Count==1;},"latest query");Check(browser.Results[0].Title=="Fast","cancelled old request cannot replace newer search");
  int requests=fake.Searches;browser.Search(false);Wait(delegate{browser.Poll();return !browser.Searching;},"cache");Check(browser.Cached && fake.Searches==requests,"fresh search cache avoids request");browser.Query.Text="missing";fake.Fail=true;browser.Search(false);Wait(delegate{browser.Poll();return !browser.Searching;},"offline error");Check(browser.Error.Contains("Offline"),"network errors exposed for retry");fake.Fail=false;
  int imported=0;string downloaded=null;browser.Downloaded=delegate(MirrorSet set,string path){imported++;downloaded=path;};browser.Download(real[0],true);Wait(delegate{browser.Poll();return !browser.Downloading && imported==1;},"download");Check(fake.LastDownload.EndsWith(real[0].Id+"n") && File.Exists(downloaded),"no-video proxy download published to Imports");Check(!File.Exists(downloaded+".part"),"partial archive not left for importer");
  fake.BadZip=true;browser.Download(new MirrorSet{Id=987,Title="invalid"},false);Wait(delegate{browser.Poll();return !browser.Downloading && browser.DownloadError!="";},"bad archive");Check(browser.DownloadError.Contains("archive") && imported==1 && !File.Exists(Path.Combine(root,"Imports/hinai-987.osz")),"non-ZIP responses never enter importer");
  fake.BadZip=false;fake.HoldDownload=true;browser.Download(new MirrorSet{Id=988},true);browser.CancelDownload();Wait(delegate{browser.Poll();return !browser.Downloading && browser.DownloadError!="";},"cancel archive");Check(imported==1 && browser.DownloadError.Contains("cancelled"),"cancelled download is not imported");
  fake.HoldDownload=false;var ui=new LazerUi {Animate=false,OnlineBrowser=browser};ui.OpenOnlineBrowser();Wait(delegate{browser.Poll();return !browser.Searching;},"open screen");var surface=new SvgUiSurface("port/Assets");ui.Draw(surface,0);surface.Save("build/ui-preview/online-beatmaps.svg");Check(ui.Screen==UiScreen.BeatmapListing && ui.SharedToolbarVisible,"browse is linked to shared toolbar");ui.MenuPointer(0,110,130);ui.MenuPointer(2,110,130);var detail=new SvgUiSurface("port/Assets");ui.Draw(detail,1);detail.Save("build/ui-preview/online-beatmap-detail.svg");string json=File.ReadAllText("build/ui-preview/online-beatmap-detail.svg");Check(json.Contains("download .osz") && json.Contains("skip video"),"card opens difficulty details and download controls");
  Console.WriteLine("PASS: "+checks+" mirror JSON, live schema, encoding, cancellation, paging, cache, download publication and browser UI checks");return 0;
 }finally{Directory.Delete(root,true);}}
}
